const s=wb.getWorksheet('HR ');
const f=`=SUMIFS(GK3:GK21,GK3:GK21,"<>#N/A",$GO$3:$GO$21,"yes")+SUMIFS(GR3:GR21,GR3:GR21,"<>#N/A",GR3:GR21,"<>#REF!",$GO$3:$GO$21,"yes")`;
const c=s.getRange('GK29');
c.setValue(f);
const cell=c.getCell();
log('GK29', cell.getValue(), cell.getText(), cell.getFormula());
log('plain', await wb.evaluate(`='HR '!GK28`));
log('GKyes', await s.getRange('A1').getWorkbook?.());
log('check', await wb.evaluate(`=SUMPRODUCT(('HR '!GO3:GO21="yes")*'HR '!GK3:GK21)+AGGREGATE(9,6,'HR '!GR3:GR21/('HR '!GO3:GO21="yes"))`));
log('GR8', wb.getRange("'HR '!GR8").getCell().getValue(), 'GO8', wb.getRange("'HR '!GO8").getCell().getValue());
